/// 辺の情報の型を E とする、無向木の全方位木DP。
///
/// - 頂点IDは 0..n。
/// - 無向辺を1回追加するだけでよい。
/// - E を複製せず、すべて参照で受け渡す。
/// - solve に渡したモノイドに従って各方向の情報をまとめる。
pub struct Rerooting<E> {
    // graph[v] = (隣接頂点ID, 辺ID)。辺の追加順を保持する。
    graph: Vec<Vec<(usize, usize)>>,
    // 無向辺のデータの実体。両方向で同じデータを参照する。
    edges: Vec<E>,
} // end of struct Rerooting

impl<E> Rerooting<E> {
    /// 頂点数nのグラフ作成
    pub fn new(n: usize) -> Self {
        Self {
            graph: vec![Vec::new(); n],
            edges: Vec::new(),
        }
    } // end of constructor

    // 無向辺 (u, v) とそのデータを登録し、辺IDを返す
    pub fn add_edge(&mut self, u: usize, v: usize, data: E) -> usize {
        let n = self.graph.len();
        debug_assert!(u < n && v < n, "頂点IDが範囲外です");
        debug_assert_ne!(u, v, "自己ループは追加できません");

        let id = self.edges.len();
        self.edges.push(data);
        self.graph[u].push((v, id));
        self.graph[v].push((u, id));
        return id;
    } // end of method

    /// 全頂点を根としたDPを計算する
    ///     
    /// # 各コールバックの意味
    ///
    /// - monoid: ある頂点へ隣接方向から届く情報 M::S の集約方法。
    /// - add_vertex(v, merged) -> V: 頂点 v 自身を追加した部分木DP。
    /// - add_edge(from, to, edge_data, dp) -> M::S:
    ///   from 側の部分木DPを、辺を越えて to に渡す寄与へ変換する。
    ///
    /// add_vertex と add_edge の結果は、同じ引数なら同じ値になるようにする。
    /// どちらもモノイドの結合順を含む隣接リスト順を尊重する。
    ///
    /// # 前提と計算量
    ///
    /// グラフは木であること（空グラフも可）。木でない場合はパニックする。
    /// モノイド演算・コールバック1回が O(1) なら、時間・空間とも O(N)。
    /// M::S と V に Clone 制約は必要ない。
    pub fn solve<M, V, FVertex, FEdge>(&self, monoid: &M, add_vertex: FVertex, add_edge: FEdge) -> Vec<V>
    where
        M: Monoid,
        FVertex: Fn(usize, &M::S) -> V,
        FEdge: Fn(usize, usize, &E, &V) -> M::S,
    {
        let n = self.graph.len();
        returnif!(n == 0, Vec::new());

        // 木の必要条件である「辺の数 = 頂点数 - 1」を確認する。
        debug_assert_eq!(self.edges.len(), n - 1, "辺の数が木の条件を満たしません");

        // ------------------------------------------------------------
        // 1. 頂点0を仮の根にして、親と親辺、および探索順を求める。
        // ------------------------------------------------------------
        // n はどの頂点IDにもならないので、未訪問を表す番兵に使う。
        let mut parent = vec![n; n];
        let mut parent_edge = vec![usize::MAX; n];
        let mut order = Vec::with_capacity(n);
        parent[0] = 0;
        order.push(0);

        // Vecをキューとして走査。再帰しないので深い気でも安全
        let mut head = 0;
        while head < order.len() {
            let v = order[head];
            head += 1;

            for &(to, id) in &self.graph[v] {
                // 親へ戻るだけ
                continueif!(to == parent[v]);

                // すでに訪問していると閉路や多重辺など
                debug_assert_eq!(parent[to], n, "閉路または多重辺が見つかりました");
                parent[to] = v;
                parent_edge[to] = id;
                order.push(to);
            }
        }
        debug_assert_eq!(order.len(), n, "グラフが連結ではありません");

        // ------------------------------------------------------------
        // 2. 子から親へ、部分木の寄与を計算する（下から上のDP）。
        // ------------------------------------------------------------
        // to_parent[v] は「頂点vの側から親へ辺を越えて届く M::S」。
        // すべて Option にすることで、値の Clone を要求しない。
        let mut to_parent: Vec<Option<M::S>> = (0..n).map(|_| None).collect();
        for &v in order.iter().rev() {
            // この時点で全ての子の to_parentは計算済み
            let mut merged = monoid.identity();
            for &(to, _) in &self.graph[v] {
                continueif!(to == parent[v]);
                let contribution = to_parent[to].as_ref().expect("子の寄与が未計算です");
                merged = monoid.combine(&merged, contribution);
            }

            // 頂点0には親が無いのので、親に渡す寄与は不要
            if v != 0 {
                let dp = add_vertex(v, &merged);
                let edge = &self.edges[parent_edge[v]];
                to_parent[v] = Some(add_edge(v, parent[v], edge, &dp));
            }
        }

        // ------------------------------------------------------------
        // 3. 親から子へ寄与を配り、各頂点を根とする答えを作る。
        // ------------------------------------------------------------
        // from_parent[v] は、親側から辺を越えて頂点vへ届く寄与。
        let mut from_parent: Vec<Option<M::S>> = (0..n).map(|_| None).collect();
        let mut answers: Vec<Option<V>> = (0..n).map(|_| None).collect();

        for &v in &order {
            let degree = self.graph[v].len();

            // prefix[i] = 隣接方向の先頭i個を順序どおりに結合した値
            let mut prefix = Vec::with_capacity(degree + 1);
            prefix.push(monoid.identity());
            for &(to, _) in &self.graph[v] {
                let contribution = if to == parent[v] {
                    // 根0以外は、親からの寄与を使う。
                    from_parent[v].as_ref().expect("親からの寄与が未計算です")
                } else {
                    // 子からの寄与は、下から上のDPで確定済み。
                    to_parent[to].as_ref().expect("子からの寄与が未計算です")
                };
                let next = monoid.combine(prefix.last().expect("単位元がありません"), contribution);
                prefix.push(next);
            }

            // 全方向を結合した値から、vを根とするDPを作成
            answers[v] = Some(add_vertex(v, prefix.last().expect("単位元がありません")));

            // suffixには現在位置より右側の寄与を累積する
            // prefix[i]とsuffixを結合すればiを除外できる
            let mut suffix = monoid.identity();
            for i in (0..degree).rev() {
                let (to, id) = self.graph[v][i];

                // 子の方向だけ、親側の寄与を新しく計算して渡す
                if to != parent[v] {
                    let without_child = monoid.combine(&prefix[i], &suffix);
                    let dp = add_vertex(v, &without_child);
                    from_parent[to] = Some(add_edge(v, to, &self.edges[id], &dp));
                }

                // 結合順が重要、 i番目の寄与はsuffixの左に
                let contribution = if to == parent[v] {
                    from_parent[v].as_ref().expect("親からの寄与が未計算です")
                } else {
                    to_parent[to].as_ref().expect("子からの寄与が未計算です")
                };
                suffix = monoid.combine(contribution, &suffix);
            }
        }

        // 結果は全頂点分計算済み。順序は頂点ID順になる。
        return answers.into_iter().map(|value| value.expect("頂点の答えが未計算です")).collect();
    }
}
